        list.forEach { q ->
          q.diagramSpec?.let { spec ->
            put("${subjectId}_${q.id}", spec)
            put(q.id, spec)
          }
        }
      }
    }
  }

  fun diagramSpecForEntityId(entityId: String): QuestionDiagramSpec? =
    diagramLookupByEntityId[entityId]
}
